const htmlData = $('Website Crawler').first().json;
const html = htmlData.body || htmlData.data || htmlData || '';
const htmlStr = typeof html === 'string'? html : JSON.stringify(html);
const pageSpeed = $('PageSpeed Insights API - REAL METRICS').first()?.json || {};
const lh = pageSpeed.lighthouseResult || {};
const categories = lh.categories || {};
const audits = lh.audits || {};
const titleMatch = htmlStr.match(/<title[^>]*>(.*?)<\/title>/i);
const metaDescMatch = htmlStr.match(/<meta[^>]*name=[\"']description[\"'][^>]*content=[\"']([^\"']*)[\"']/i) || htmlStr.match(/<meta[^>]*content=[\"']([^\"']*)[\"'][^>]*name=[\"']description[\"']/i);
const h1Matches = (htmlStr.match(/<h1[^>]*>/gi) || []);
const allLinks = [...htmlStr.matchAll(/<a[^>]*href=[\"'](https?:\/\/[^\"']+)[\"']/gi)].map(m=>m[1]);
let internalLinks = 0;
try { const host = new URL($('Webhook Trigger').first().json.url).hostname; internalLinks = allLinks.filter(l => { try { return new URL(l).hostname === host; } catch { return false; } }).length; } catch {}
const perfScore = categories.performance? Math.round(categories.performance.score * 100) : null;
const seoScore = categories.seo? Math.round(categories.seo.score * 100) : null;
return [{ json: { url: $('Webhook Trigger').first().json.url, realMetrics: { performanceScore: perfScore, seoScore: seoScore, accessibilityScore: categories.accessibility? Math.round(categories.accessibility.score*100): null, bestPracticesScore: categories['best-practices']? Math.round(categories['best-practices'].score*100): null, LCP: audits['largest-contentful-paint']?.displayValue || 'N/A', CLS: audits['cumulative-layout-shift']?.displayValue || 'N/A', speedIndex: audits['speed-index']?.displayValue || 'N/A', FCP: audits['first-contentful-paint']?.displayValue || 'N/A', hasTitle:!!titleMatch, titleText: titleMatch? titleMatch[1].substring(0,120) : 'MISSING', hasMetaDesc:!!metaDescMatch, metaDescText: metaDescMatch? metaDescMatch[1].substring(0,160) : 'MISSING', h1Count: h1Matches.length, totalLinks: allLinks.length, internalLinks: internalLinks, externalLinks: allLinks.length - internalLinks }, rawHtmlLength: htmlStr.length, text: $('HTML to Text').first().json.text || '' } }];

const input = $('SEO Technical Checker - REAL').first().json;
const text = input.text || '';
const url = input.url;
const CHUNK_SIZE = 1000;
const OVERLAP = 200;
const results = [];
let start = 0;
while (start < text.length) {
 let end = Math.min(start + CHUNK_SIZE, text.length);
 if (end < text.length) {
 const lastPara = text.lastIndexOf('\n\n', end);
 const lastDot = text.lastIndexOf('. ', end);
 const cut = Math.max(lastPara, lastDot);
 if (cut > start + 500) end = cut + 1;
 }
 const chunk = text.slice(start, end).trim();
 if (chunk.length > 100) results.push({ json: { chunk, url, index: results.length } });
 start = end - OVERLAP;
 if (results.length >= 20) break;
}
if (results.length === 0) results.push({ json: { chunk: text.slice(0,1000) || 'No content found', url, index: 0 } });
return results;

// V7.2 FIXED - Robust Vector Search
const genEmbeds = $('Generate Embeddings - REAL VECTOR').all;
const splitterData = $('Text Splitter - PRO 1000/200').all;
const qData = $('User Query Embedding').first()?.json;
const queryEmbedding = qData?.embedding?.values || qData?.embedding || [];

function cosine(a,b){
  if(!a?.length || !b?.length) return 0;
  let dot=0, ma=0, mb=0;
  const len = Math.min(a.length,b.length);
  for(let i=0;i<len;i++){ dot+=a[i]*b[i]; ma+=a[i]*a[i]; mb+=b[i]*b[i]; }
  const denom = Math.sqrt(ma)*Math.sqrt(mb);
  return denom===0?0:dot/denom;
}

let vectors = genEmbeds.map((item, i) => {
  const split = splitterData[i]?.json || splitterData[0]?.json || {};
  const chunk = split.chunk || item.json.chunk || '';
  const emb = item.json.embedding?.values || item.json.embedding || [];
  return { chunk, embedding: emb, url: split.url || $('Webhook Trigger').first().json.url, index: i, score: 0 };
}).filter(v => v.chunk && v.embedding.length > 0);

if(queryEmbedding.length > 0){
  vectors.forEach(v => v.score = cosine(v.embedding, queryEmbedding));
  vectors.sort((a,b) => b.score - a.score);
} else {
  vectors.forEach((v,i)=> v.score = 5-i);
}

const topVectors = vectors.slice(0,5);
return [{
  json: {
    vectors: topVectors.map(v => ({ chunk: v.chunk, url: v.url, score: Number(v.score?.toFixed(4)) })),
    count: vectors.length,
    topCount: topVectors.length,
    status: 'V7.2-FIXED-real-cosine',
    hasQueryEmbed: queryEmbedding.length > 0,
    realMetrics: $('SEO Technical Checker - REAL').first().json.realMetrics
  }
}];
